// Bounded exact-decimal contract. Generated by tools/fm3/build-wah-exact-table.py
// from the independently replayed hardware capture and four-mode consensus.
// No firmware executable, Python runtime, network or device I/O is needed here.
import fs from 'node:fs';
import {createHash} from 'node:crypto';
import {isDeepStrictEqual} from 'node:util';
import {inspectStructure} from './drive-collector/fm3-prototype.mjs';
import {auditModifiers} from './fm3-modifier-audit.mjs';
const check=(v,m)=>{if(!v)throw Error('Wah exact Min/Max: '+m);};
const bytes=fs.readFileSync(new URL('../references/wah-minmax-exact.json',import.meta.url));
check(createHash('sha256').update(bytes).digest('hex')==='468ab4c092ccf5fae9b4dda38cacb5d3a64f35fc78b850218e70588ff0a8c54b','evidence table hash mismatch');
const data=JSON.parse(bytes);
export const exactWahPolicy='exact-wah-cent-fw13-hw1';
const own=(o,k)=>Object.hasOwn(o,k);
export function exactWahCapability(){return {
 field:'modifiers.wahMinMaxExact',policy:exactWahPolicy,status:'bounded-exact-input',
 fields:['min','max'],input:'Exact decimal strings 0.00..10.00, step 0.01; at least one field',
 targetScope:structuredClone(data.targetScope),countsPerField:{...data.countsPerField},
 evidenceFile:'references/wah-minmax-exact.json',captureSha256:data.captureSha256,
 fullRangeEncodingProven:false,runtimeModeAtStoreProven:false,deviceImportTested:false,
 interpretation:'Exact requested values; not recovered mouse/keyboard input or observed display lookup',
 conflicts:'Do not specify the same field using wahMin or wahControls.max',
 requires:'Final External 1 -> Wah1 Control ALL; existing retained configuration checks',deviceIO:false};}
export function planWahExact(request){
 check(request&&typeof request==='object'&&!Array.isArray(request)&&request.policy===exactWahPolicy&&
   Object.keys(request).every(k=>['policy','min','max'].includes(k))&&(own(request,'min')||own(request,'max')),
   'explicit policy and min and/or max required');
 const changes=[];
 for(const [field,pid] of [['min',1],['max',2]]){
  if(!own(request,field))continue;
  const value=request[field];
  check(typeof value==='string'&&/^(?:[0-9]\.[0-9]{2}|10\.00)$/.test(value),'expected exact decimal string 0.00..10.00');
  const [whole,cents]=value.split('.'),row=data.rows[Number(whole)*100+Number(cents)];
  check(row?.[0]===value,'input absent from bounded table');
  changes.push({field,pid,offset:1584+2*pid,exactDecimal:value,normalizedBits:row[1],raw:row[2],
   evidenceBasis:row[3],measuredSteps:[...row[pid===1?4:5]]});
 }
 return {policy:exactWahPolicy,changes,captureSha256:data.captureSha256,
  fullRangeEncodingProven:false,runtimeModeAtStoreProven:false,deviceImportTested:false,
  allRequestedInputsHardwareMeasured:changes.every(c=>c.evidenceBasis==='hardware-exact-input')};
}
export function renderWahExact(plan){
 if(!plan)return [];
 return plan.changes.map(c=>`${c.field==='min'?'Min':'Max'}: täpne sisestussiht ${c.exactDecimal}; salvestatud kood ${c.raw}; ${c.evidenceBasis==='hardware-exact-input'?'sama sisend riistvaral mõõdetud':'nelja mudeli kokkulangevus; seda sisendit riistvaral ei mõõdetud'}.`).concat([
  'Täpne sisestussiht ei ole uus ekraanivaatlus. Kogu vahemiku riistvarakinnitus puudub; selle genereeritud faili import ja pedaali/heli kontroll on tegemata.']);
}
export function verifyWahExactOutput(report,syx,txt,spec){
 const request=(spec?.composer??spec)?.modifiers?.wahMinMaxExact;
 if(request===undefined&&!report.modifierEdit?.exactMinMax)return;
 check(request!==undefined,'exact report has no matching specification');
 const plan=planWahExact(request);
 check(isDeepStrictEqual(report.modifierEdit?.exactMinMax,plan),'exact report differs from requested evidence');
 const body=Buffer.from(inspectStructure(syx).raw.body);
 const audit=auditModifiers(syx),m=audit.modifiers[0];
 check(m.offset===1584&&m.source===14&&m.effectId===94&&m.pid===5&&m.channel===0&&
   m.secondarySource===0&&m.operation===0&&!m.uncertain,'final target mismatch');
 check(audit.contextScan.status==='complete'&&m.targetContext?.recordPresence==='present'&&
   m.targetContext?.gridPresence==='present'&&m.targetContext?.sceneStatus==='known',
   'final Wah target context unresolved');
 check(!audit.modifiers.slice(1).some(x=>(x.effectId===94&&x.pid===5)||(x.active&&x.effectId===0&&x.pid===5)),
   'competing final Wah target');
 for(const c of plan.changes){
  check(body.readUInt16LE(c.offset)===c.raw,'final '+c.field+' differs from exact request');
  const row=c.field==='min'?report.modifierEdit.min:report.modifierEdit.controls?.max;
  check(row?.after===c.raw&&row?.display===null&&row?.exactDecimal===c.exactDecimal,'field report mismatch');
 }
 for(const line of renderWahExact(plan))check(txt.includes(line),'TXT exact-input evidence mismatch');
}
